"""Compile validated data to bounded Opentrons API 2.20 calls."""

from .labware import MODULE_LOAD_NAMES
from .models import Delay, Incubate, MagneticHold, Mix, Protocol, Shake, ThermalCycle
from .validation import transfers, validate


def compile_protocol(protocol: Protocol) -> dict:
    report = validate(protocol)
    lines = [
        "# Generated by SCP-Lab. Simulation example; hardware use has not been validated.",
        "from opentrons import protocol_api",
        "",
        f"metadata = {{'protocolName': {protocol.name!r}, 'author': 'SCP-Lab'}}",
        "requirements = {'robotType': 'OT-2', 'apiLevel': '2.20'}",
        "",
        "def run(protocol: protocol_api.ProtocolContext):",
        "    labware = {}",
        "    modules = {}",
    ]

    def emit(code):
        lines.append("    " + code)

    for module in protocol.setup.modules:
        location = "" if module.kind == "thermocycler" else f", {str(module.slot)!r}"
        emit(
            f"modules[{module.id!r}] = protocol.load_module({MODULE_LOAD_NAMES[module.kind]!r}{location})"
        )
        if module.kind == "thermocycler":
            emit(f"modules[{module.id!r}].open_lid()")
        elif module.kind == "magnetic":
            emit(f"modules[{module.id!r}].disengage()")
        elif module.kind == "heater_shaker":
            emit(f"modules[{module.id!r}].close_labware_latch()")
    module_ids = {x.id for x in protocol.setup.modules}
    for lw in protocol.setup.labware:
        loader = f"modules[{lw.location!r}]" if lw.location in module_ids else "protocol"
        location = "" if lw.location in module_ids else f", {lw.location!r}"
        emit(f"labware[{lw.id!r}] = {loader}.load_labware({lw.load_name!r}{location})")
    pipette = protocol.setup.pipette
    if pipette:
        racks = ", ".join(f"labware[{x!r}]" for x in pipette.tip_racks)
        emit(
            f"pipette = protocol.load_instrument({pipette.model!r}, {pipette.mount!r}, tip_racks=[{racks}])"
        )

    def ref(well):
        return f"labware[{well.labware!r}][{well.well!r}]"

    locations = {x.id: x.location for x in protocol.setup.labware}
    for step in protocol.steps:
        emit(f"protocol.comment({('SCP-Lab step ' + step.id + ': ' + step.action)!r})")
        for source, destination, volume in transfers(step):
            emit("pipette.pick_up_tip()")
            emit(f"pipette.aspirate({volume!r}, {ref(source)})")
            emit(f"pipette.dispense({volume!r}, {ref(destination)})")
            emit("pipette.drop_tip()")
        if isinstance(step, Mix):
            emit("pipette.pick_up_tip()")
            emit(f"pipette.mix({step.repetitions!r}, {step.volume_ul!r}, {ref(step.sample)})")
            emit("pipette.drop_tip()")
        if isinstance(step, (Incubate, Shake, ThermalCycle, MagneticHold)):
            module = f"modules[{locations[step.labware]!r}]"
            if isinstance(step, Incubate):
                emit(f"{module}.set_temperature({step.temperature_c!r})")
                emit(f"protocol.delay(seconds={step.duration_s!r})")
                emit(f"{module}.deactivate()")
            elif isinstance(step, Shake):
                emit(f"{module}.close_labware_latch()")
                emit(f"{module}.set_and_wait_for_shake_speed({step.speed_rpm!r})")
                emit(f"protocol.delay(seconds={step.duration_s!r})")
                emit(f"{module}.deactivate_shaker()")
            elif isinstance(step, ThermalCycle):
                emit(f"{module}.close_lid()")
                emit(f"{module}.set_lid_temperature({step.lid_temperature_c!r})")
                profile = [
                    {"temperature": s.temperature_c, "hold_time_seconds": s.duration_s}
                    for s in step.profile
                ]
                emit(
                    f"{module}.execute_profile(steps={profile!r}, repetitions={step.cycles!r}, block_max_volume={step.block_max_volume_ul!r})"
                )
                emit(f"{module}.deactivate_lid()")
                emit(f"{module}.deactivate_block()")
                emit(f"{module}.open_lid()")
            elif isinstance(step, MagneticHold):
                emit(f"{module}.engage(height_from_base={step.height_from_base_mm!r})")
                emit(f"protocol.delay(seconds={step.duration_s!r})")
                emit(f"{module}.disengage()")
        if isinstance(step, Delay):
            emit(f"protocol.delay(seconds={step.duration_s!r})")
    return {
        "code": "\n".join(lines) + "\n",
        "validation": report,
        "api_level": "2.20",
        "device_id": "ot2",
    }
